<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/assets/css/app.css"><title>سناریوهای تست</title></head><body><header><b>✓ آزمون‌یار</b><nav><a href="/dashboard">داشبورد</a><a href="/projects">پروژه‌ها</a><a href="/test-cases">سناریوها</a><a href="/test-runs">دوره‌ها</a><a href="/my-tasks">کارتابل</a></nav></header><main class="app"><span>مدیریت کیفیت</span><h1>سناریوهای تست</h1><p>سناریوها را با کد یکتا، اولویت و نتیجهٔ مورد انتظار ثبت کنید.</p><?php if(session('error')):?><div class="alert error"><?=esc(session('error'))?></div><?php endif ?><?php if(session('message')):?><div class="alert"><?=esc(session('message'))?></div><?php endif ?><section><h2>سناریوی جدید</h2><form method="post" class="grid"><label>پروژه<select name="project_id" required><option value="">انتخاب کنید</option><?php foreach($projects as $p):?><option value="<?=$p['id']?>"><?=esc($p['name'])?></option><?php endforeach?></select></label><label>کد سناریو<input name="code" required placeholder="TC-001"></label><label>عنوان<input name="title" required placeholder="ورود کاربر معتبر"></label><label>اولویت<select name="priority"><option>MEDIUM</option><option>HIGH</option><option>CRITICAL</option><option>LOW</option></select></label><label class="wide">نتیجهٔ مورد انتظار<textarea name="expected_result" required></textarea></label><button class="btn">ثبت پیش‌نویس</button></form></section><section><h2>گرید سناریوها</h2><table><tr><th>کد</th><th>عنوان</th><th>پروژه</th><th>اولویت</th><th>وضعیت</th></tr><?php foreach($cases as $c):?><tr><td><?=esc($c['code'])?></td><td><?=esc($c['title'])?></td><td><?=esc($c['project_name'])?></td><td><?=esc($c['priority'])?></td><td><i><?=esc($c['status'])?></i></td></tr><?php endforeach?></table></section></main></body></html>
